fn is_min_heap(a: &Vec<i32>) -> bool {
    let n = a.len();
    
    // Check each parent node
    let mut i = 0;
    while i < n / 2 {
        let parent = a[i];
        
        // Check left child (always exists for parents in range [0, n/2))
        let left_idx = 2 * i + 1;
        if left_idx < n && a[left_idx] < parent {
            return false;
        }
        
        // Check right child (may not exist)
        let right_idx = 2 * i + 2;
        if right_idx < n && a[right_idx] < parent {
            return false;
        }
        
        i += 1;
    }
    
    true
}